import React from 'react';
import { graphql } from 'gatsby';
import Layout from '../components/Layout';
import BentoGrid from '../components/BentoGrid';
import { useLanguage } from '../context/LanguageContext';

const IndexPage = ({ data }) => {
  const { language } = useLanguage();
  const markdownNodes = data.allMarkdownRemark.nodes;

  // Filter content based on active language
  const heroData = markdownNodes.find(
    (node) => node.frontmatter.section === 'hero' && node.frontmatter.lang === language
  );

  const aboutData = markdownNodes.find(
    (node) => node.frontmatter.section === 'about' && node.frontmatter.lang === language
  );

  const worksData = markdownNodes.filter(
    (node) => node.frontmatter.section === 'works' && node.frontmatter.lang === language
  );

  return (
    <Layout>
      <BentoGrid 
        heroData={heroData} 
        aboutData={aboutData} 
        worksData={worksData} 
      />
    </Layout>
  );
};

export const query = graphql`
  query {
    allMarkdownRemark {
      nodes {
        id
        html
        frontmatter {
          title
          subtitle
          lang
          section
          category
          tags
          order
        }
      }
    }
  }
`;

export default IndexPage;
